function familyChooseWeek(){
 let base=familyAddDays(familyNextTuesday(),-14);const d=familyDialog('가족 숭배',`<div class="family-week-nav"><button type="button" data-week-nav="-1" aria-label="이전 주">‹</button><button type="button" data-week-nav="1" aria-label="다음 주">›</button></div><div class="family-week-list"></div>`),list=d.querySelector('.family-week-list');
 function render(){list.innerHTML=Array.from({length:5},(_,i)=>{const anchor=familyAddDays(base,i*7),item=familySession(anchor),saved=!!familySessionNote(anchor);return `<button type="button" data-week="${esc(anchor)}"><span><strong>${esc(familyDayLabel(item.date,true))}</strong>${saved&&item.date!==anchor?`<small>기본 ${esc(familyDayLabel(anchor))}</small>`:''}</span>${item.topic?`<span>${esc(item.topic)}</span>`:''}<span aria-hidden="true">→</span></button>`}).join('');list.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{const anchor=b.dataset.week;d.close();location.hash=familySessionLink(anchor)})}
 d.querySelectorAll('[data-week-nav]').forEach(b=>b.onclick=()=>{base=familyAddDays(base,Number(b.dataset.weekNav)*35);render()});render();
}
function familyRenderSyncNotice(){const main=document.querySelector('.family-detail');if(!main||main.querySelector('.family-sync-notice'))return;const box=document.createElement('div');box.className='family-sync-notice';box.setAttribute('role','status');box.innerHTML='<span>저장했어요. 최신 화면을 불러오지 못했어요.</span><button type="button">다시 불러오기</button>';main.prepend(box);box.querySelector('button').onclick=async()=>{const b=box.querySelector('button');b.disabled=true;try{await familyReloadNotes();familySyncPending=false;const anchor=decodeURIComponent(location.hash.split('/')[3]||'');if(familyParseDate(anchor))familySessionView(anchor)}catch{b.disabled=false;box.querySelector('span').textContent='연결을 확인한 뒤 다시 불러와 주세요.'}}}
